from copy import deepcopy

from solution import page

rows = [
    {\"id\": \"z\", \"score\": 4, \"team\": \"a\", \"extra\": {\"keep\": True}},
    {\"id\": \"x\", \"score\": 9, \"team\": \"b\"},
    {\"id\": \"a\", \"score\": 4, \"team\": \"a\"},
    {\"id\": \"m\", \"score\": 4, \"team\": \"b\"},
    {\"id\": \"q\", \"score\": -1, \"team\": \"a\"},
]
original = deepcopy(rows)
assert page(rows, 2, None, None) == {\"rows\": [rows[1], rows[2]], \"next\": [4, \"a\"]}
assert page(rows, 1, [4, \"m\"], \"a\") == {\"rows\": [rows[0]], \"next\": [4, \"z\"]}
assert page(rows, 2, [4, \"c\"], \"a\") == {\"rows\": [rows[0], rows[4]], \"next\": None}
assert page(rows, 1, [4, \"z\"], \"a\") == {\"rows\": [rows[4]], \"next\": None}
assert page(rows, 50, [-1, \"q\"], \"a\") == {\"rows\": [], \"next\": None}
assert page(rows, 50, None, \"missing\") == {\"rows\": [], \"next\": None}
assert rows == original
for limit in (0, 51, 1.0, True):
    try:
        page(rows, limit, None, None)
    except ValueError:
        continue
    raise AssertionError(f\"accepted invalid limit {limit"'!r}")
print("Pagination edge cases passed")
PY'

